#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

// Pares de faces opostas:
// A (0) com F (5)
// B (1) com D (3)
// C (2) com E (4)
int get_opposite(int face_idx) {
    switch (face_idx) {
        case 0: return 5;
        case 1: return 3;
        case 2: return 4;
        case 3: return 1;
        case 4: return 2;
        case 5: return 0;
    }
    return -1;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int n;
    if (!(cin >> n)) return 0;

    vector<vector<int>> dice(n, vector<int>(6));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < 6; ++j) {
            cin >> dice[i][j];
        }
    }

    int max_total_sum = 0;

    // O primeiro dado tem 6 possíveis orientações para a face inferior (índice 0 a 5)
    for (int bottom_face_idx = 0; bottom_face_idx < 6; ++bottom_face_idx) {
        int current_sum = 0;
        int current_top_val = 0;

        // Processa o primeiro dado
        int b_idx = bottom_face_idx;
        int t_idx = get_opposite(b_idx);
        current_top_val = dice[0][t_idx];

        int best_side = 0;
        for (int j = 0; j < 6; ++j) {
            if (j != b_idx && j != t_idx) {
                best_side = max(best_side, dice[0][j]);
            }
        }
        current_sum += best_side;

        // Processa os dados seguintes
        for (int i = 1; i < n; ++i) {
            // A base do dado i deve ter valor igual a current_top_val
            int next_b_idx = -1;
            for (int j = 0; j < 6; ++j) {
                if (dice[i][j] == current_top_val) {
                    next_b_idx = j;
                    break;
                }
            }
            int next_t_idx = get_opposite(next_b_idx);
            current_top_val = dice[i][next_t_idx];

            best_side = 0;
            for (int j = 0; j < 6; ++j) {
                if (j != next_b_idx && j != next_t_idx) {
                    best_side = max(best_side, dice[i][j]);
                }
            }
            current_sum += best_side;
        }

        max_total_sum = max(max_total_sum, current_sum);
    }

    cout << max_total_sum << "\n";

    return 0;
}
